Translate the following GNU C++11 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>

using namespace std;
typedef long long LL;
const int N=10, M=25, S=1048580, MOD=1000000007;
int n,p[N][N],ma[N][N],bin[M],a[N],b[N],f[S],g[S],tot,id[70],pts[M][N],sta[M];
bool vis[N];

int power(int base,int exp)
{
    int result=1;
    while (exp)
    {
        if (exp&1) result=(LL)result*base%MOD;
        base=(LL)base*base%MOD; exp>>=1;
    }
    return result;
}

void setup_variables()
{
    bin[0]=1;
    for (int i=1;i<=20;i++) bin[i]=bin[i-1]*2;
    scanf("%d",&n);
    int inv=power(100,MOD-2);
    for (int i=1;i<=n;i++)
        for (int j=1;j<=n;j++)
            scanf("%d",&p[i][j]),p[i][j]=(LL)p[i][j]*inv%MOD;
    while (n<6) n++, p[n][n]=1;
}

bool can_form_match(int x)
{
    if (x>3) return true;
    for (int i=1;i<=3;i++)
        if (!vis[i]&&ma[a[x]][b[i]])
        {
            vis[i]=true;
            if (can_form_match(x+1)) return true;
            vis[i]=false;
        }
    return false;
}

void explore_options(int x,int y,int prob)
{
    if (x>3)
    {
        int sum=0;
        for (int i=1;i<=tot;i++)
        {
            for (int j=1;j<=3;j++) b[j]=pts[i][j];
            if (can_form_match(1)) sum+=bin[i-1];
        }
        (f[sum]+=prob)%=MOD;
        return;
    }
    ma[a[x]][y]=0;
    if (y==n) explore_options(x+1,1,(LL)prob*(1-p[a[x]][y])%MOD);
    else explore_options(x,y+1,(LL)prob*(1-p[a[x]][y])%MOD);
    ma[a[x]][y]=1;
    if (y==n) explore_options(x+1,1,(LL)prob*p[a[x]][y]%MOD);
    else explore_options(x,y+1,(LL)prob*p[a[x]][y]%MOD);
}

void generate_state_combinations(int x,int y,int s)
{
    if (y==3)
    {
        id[s]=++tot;sta[tot]=s;
        for (int i=1;i<=3;i++) pts[tot][i]=a[i];
        return;
    }
    if (x>n) return;
    generate_state_combinations(x+1,y,s);
    a[y+1]=x;
    generate_state_combinations(x+1,y+1,s+bin[x-1]);
}

void compute_prefix()
{
    for (int i=0;i<tot;i++)
        for (int j=0;j<bin[tot];j++)
            if (j&bin[i]) (g[j]+=g[j^bin[i]])%=MOD;
}

int main()
{
    setup_variables();
    generate_state_combinations(1,0,0);
    a[1]=1; a[2]=2; a[3]=3;
    explore_options(1,1,1);
    for (int i=0;i<bin[tot];i++)
    {
        int t=0;
        for (int j=1;j<=tot;j++)
        {
            int rev=id[bin[n]-1-sta[j]];
            if (i&bin[j-1]) t+=bin[rev-1];
        }
        g[t]=f[i]; f[i]=0;
    }
    a[1]=4; a[2]=5; a[3]=6;
    explore_options(1,1,1);
    compute_prefix();
    int total_result=0;
    for (int i=0;i<bin[tot];i++)
        (total_result+=(LL)f[i]*g[bin[tot]-1-i]%MOD)%=MOD;
    printf("%d\n",(1-total_result+MOD)%MOD);
    return 0;
}
